/*
 * A306351  Number of ways to split an n-cycle into connected subgraphs all
 *          having at least 4 vertices.
 * https://oeis.org/A306351
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 17, u16 n <= 34, u32 n <= 45, u64 n <= 45, u128 n <= 45,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* 
 * Formula: The OEIS A306351 sequence can be generated by the linear recurrence
 * derived from the rational generating function
 *      G(x) = (2*x^9 - 3*x^8 + x^3 - 3*x^2 + 3*x - 1)
 *            / ((x^4 + x - 1)*(x - 1)^2)
 *
 * The recurrence (valid for n >= 10) is:
 *      a(n) = 3*a(n-1) - 3*a(n-2) + a(n-3) + a(n-4)
 *             - 2*a(n-5) + a(n-6)
 * with initial values a(0)=1, a(1)=a(2)=a(3)=0, a(4)=a(5)=a(6)=a(7)=1,
 * a(8)=5, a(9)=10.
 *
 * The implementation memoises the computed terms so that repeated calls are
 * fast, regardless of the order of the indices supplied.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

/* Pre‑computed initial values for n = 0 … 9 */
static const seq_t init_vals[10] = {
    (seq_t)1, (seq_t)0, (seq_t)0, (seq_t)0,
    (seq_t)1, (seq_t)1, (seq_t)1, (seq_t)1,
    (seq_t)5, (seq_t)10
};

/* Static storage for memoised values. */
static seq_t *memo = NULL;
static size_t memo_len = 0;

/* Ensure that memo[n] exists; grow as necessary. */
static void ensure(idx_t n)
{
    /* Nothing to do if already computed. */
    if (memo_len > n) return;

    /* Grow the memo array to a suitable size. */
    size_t new_len = memo_len == 0 ? 10 : memo_len * 2;
    while (new_len <= (size_t)n) new_len <<= 1;   /* keep doubling */

    seq_t *new_mem = (seq_t *)realloc(memo, new_len * sizeof(seq_t));
    if (!new_mem) exit(EXIT_FAILURE);          /* allocation fail */
    memo = new_mem;

    /* Fill newly allocated entries.  Use the recurrence once the index
     * reaches 10. */
    for (size_t i = memo_len; i < new_len; ++i)
    {
        if (i < 10)
            memo[i] = init_vals[i];
        else
        {
            /* a(i) = 3*a(i-1) - 3*a(i-2) + a(i-3)
             *        + a(i-4) - 2*a(i-5) + a(i-6) */
            seq_t val = memo[i - 1];
            val *= (seq_t)3;
            val -= memo[i - 2] * (seq_t)3;
            val += memo[i - 3];
            val += memo[i - 4];
            val -= memo[i - 5] * (seq_t)2;
            val += memo[i - 6];
            memo[i] = val;
        }
    }
    memo_len = new_len;
}

seq_t a(idx_t n)
{
    ensure(n);
    return memo[(size_t)n];
}
